from pathlib import Path
import json,hashlib
p=Path(__file__).resolve().parent
s=(p/'src/atlas.html').read_text().replace('__ROUTE_SCRIPT__',(p/'src/routes.js').read_text()).replace('__TERRITORY_SCRIPT__',(p/'src/territories.js').read_text()).replace('__SETTLEMENT_SCRIPT__',(p/'src/settlements.js').read_text()).replace('__CELL_SCRIPT__',(p/'src/cells.js').read_text()).replace('__GEOLOGY_SCRIPT__',(p/'src/geology.js').read_text())
for token,file in [('ENCYCLOPEDIA','encyclopedia.json'),('BASEMAP','basemap.json'),('GEOGRAPHY','geography.json'),('WORLDTILES','worldtiles.json'),('GAZETTEER','gazetteer.json'),('GAZSTORIES','gazetteer_stories.json'),('ROUTES','routes.json'),('ROUTENAMES','route_names.json'),('TERRITORIES','territories.json'),('SETTLEMENTS','settlements.json'),('CELLMETRICS','cell_metrics.json'),('GEOSITES','geosites.json'),('GEOLOGY','geology.json')]:
 s=s.replace('__'+token+'__',json.dumps(json.loads((p/'data'/file).read_text()),ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
(p/'index.html').write_text(s)
files=['index.html','src/atlas.html','data/encyclopedia.json','data/basemap.json','data/geography.json','prepare_geography.py','prepare_world.py','data/worldtiles.json','data/knowledge.json','studio/index.html','data/gazetteer.json','data/gazetteer.tsv','data/gazetteer_stories.json','enrich_atlas.py','src/routes.js','data/routes.json','data/routes_sample.tsv','import_routes.py','data/route_names.json','src/territories.js','data/territories.json','data/territories_sample.tsv','import_territories.py','data/licenses/historical-basemaps-GPL-3.txt','import_expansion.py','data/gazetteer_verified.json','data/cornu_regional_sample.psv','data/cornu_global_sample.psv','enrich_heritage.py','data/heritage_additions.json','src/settlements.js','import_settlements.py','data/settlements.json','data/saudi_settlements_sample.psv','data/saudi_major_sample.psv','data/licenses/homaily-GPL-2.txt','src/cells.js','prepare_cells.py','data/cell_metrics.json','data/geosites.json','src/geology.js','prepare_geology.py','data/geology.json','data/provinces_source.psv','data/volcanic_sites.psv']
(p/'data/manifest.json').write_text(json.dumps({f:hashlib.sha256((p/f).read_bytes()).hexdigest() for f in files},indent=2))
